  "AuthScheme": {
    "name": "SpektrixAPI3",
    "mode": "SystemOwner",
    "requiredHeaders": [
      "Host",
      "Date",
      "Authorization"
    ],
    "AuthorizationHeaderPattern": "Authorization: SpektrixAPI3 <ApiLoginName>:<Signature>",
    "StringToSign": "UPPERCASE(HTTP-Method) + \"\\n\" + full-request-URL + \"\\n\" + Date-header-value + (non-GET only: \"\\n\" + BASE64(MD5(UTF8(body))))",
    "BodyHash": "BASE64(raw 16-byte MD5 of UTF-8 body); only for requests with a body (all non-GET)",
    "SigningKey": "BASE64-DECODE(ApiSecretKey) (secret is base-64 encoded; must be decoded before HMAC)",
    "Signature": "BASE64(HMAC-SHA1(decoded key, UTF8(StringToSign)) as raw 20-byte binary)",
    "DateHeader": "UTC, RFC 7231 preferred (e.g. Mon, 21 Oct 2020 07:28:00 GMT)",
    "ClientSideSigningPossible": false,
    "CredentialInputs": [
      "ClientName",
      "ApiLoginName",
      "ApiSecretKey",
      "BaseURL(optional override)"
