    "IdentityDecisions": {
      "source": "packages/Integration/connectors-registry/spektrix/sources/derived/identity-decisions.json",
      "rule": "IsPrimaryKey only where the vendor documentation proves a row identifier carried by an EXISTING IOF — or, for CustomerAddress (operator-approved, round 11b), by ONE injected parent-key IOF structured exactly like CustomerTag.customerId; otherwise the IO is Disabled (never a synthesized row index or content key as a declared PK). Re-enabling a Disabled IO needs its cited re-enable path in a later build.",
      "keyed": [
        {
          "object": "EventInstanceAvailabilityDto",
          "fields": [
            "eventInstanceId"
          ],
          "basis": "documented row identifier: GET /events/{id}/availability data[] is the per-INSTANCE availability summary and each entry''s eventInstanceId is the instance''s API ID (one entry per instance) — SOFT key"
        },
        {
          "object": "CustomerAddress",
          "fields": [
            "customerId",
            "id"
          ],
          "basis": "composite (parent key + member Id) — member addressing path: every documented single-address operation addresses ONE CustomerAddress under its Customer (PATCH / DELETE v3/customers/{id}/addresses/{addressId}, both ids Required), and a delete receives only the record key — so the key carries the parent id (CustomerTag / CustomerAgreedStatement precedent) — SOFT key",
          "addedFields": [
            {
              "name": "customerId",
              "copyOf": "CustomerTag.customerId"
            }
          ],
          "approvedBy": "operator, round 11b (adds ONE injected parent-key IOF)"
        },
        {
